select throws_ok($$select public.save_maintenance('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',null,'{"id": "dddddddd-0000-4000-8000-000000000001", "expected_version": 5, "name": "Local Oil", "distance_interval": 4000, "distance_unit": "mi", "time_interval": 1, "time_unit": "months", "upcoming_percent": 10, "due_percent": 5, "enabled": true, "update_existing": true, "schedule_versions": {}}'::jsonb)$$, '42501', null, 'Driver cannot propagate');
